PREFIX wikidata: <http://www.wikidata.org/entity/>
PREFIX schema: <http://schema.org/>
PREFIX geo: <http://www.georss.org/georss/>

SELECT ?item ?label ?p625
WHERE {
  ?item a schema:PointOfInterest .
  ?item wikidata:P625 ?p625 .

  {
    # Filter by city Q8813 (Alicante)
    ?item wikidata:P131 <http://www.wikidata.org/entity/Q8813> .
  }

  {
    # Alternative filter by country Q29 (Spain)
    # ?item wikidata:P131 <http://www.wikidata.org/entity/Q29> .
  }

  SERVICE wikibase:label {
    bd:serviceParam wikibase:language "en" .
    BIND(?item AS ?item)
    BIND(?item AS ?label)
  }
}

